function D=NB_RA_DIAGNOSTICS(X,model)
% Training-only checks of the author's RA weights; no masks or probe data.
% Initial state is the native first-k-identity initialization. This function
% never selects gamma/lambda, rescales data, or changes the fitted basis.
    validateattributes(X,{'numeric'},{'real','finite','nonempty'});
    fields={'V','mean','gamma','lambda'};
    assert(all(isfield(model,fields)),'NB:RADiagnostics','RA model fields missing.');
    [p,q,n]=size(X);k=size(model.V,2);
    assert(size(model.V,1)==q&&isequal(size(model.mean),[p q]), ...
        'NB:RADiagnostics','Training tensor and RA model dimensions differ.');
    Y=double(X)-model.mean;
    initial=describe(Y,eye(q,k),model.gamma,model.lambda);
    final=describe(Y,model.V,model.gamma,model.lambda);
    D=struct('Scope','training_only_no_selection','Gamma',model.gamma, ...
        'Lambda',model.lambda,'Rows',p*n,'FeatureDimension',p*k, ...
        'InitialRowNonzeroFraction',initial.RowNonzeroFraction, ...
        'FinalRowNonzeroFraction',final.RowNonzeroFraction, ...
        'InitialCovarianceFrobenius',initial.CovarianceFrobenius, ...
        'FinalCovarianceFrobenius',final.CovarianceFrobenius, ...
        'InitialCovarianceRank',initial.CovarianceRank, ...
        'FinalCovarianceRank',final.CovarianceRank, ...
        'InitialAllWeightsZero',initial.AllWeightsZero, ...
        'FinalAllWeightsZero',final.AllWeightsZero, ...
        'InitialZeroCovariance',initial.ZeroCovariance, ...
        'FinalZeroCovariance',final.ZeroCovariance, ...
        'InitialResidualOverGammaMedian',initial.ResidualOverGammaMedian, ...
        'FinalResidualOverGammaMedian',final.ResidualOverGammaMedian, ...
        'InitialWeightMaximum',initial.WeightMaximum,'FinalWeightMaximum',final.WeightMaximum);
end

function D=describe(Y,V,gamma,lambda)
    [p,q,n]=size(Y);covariance=zeros(q,q);nonzeroRows=0;maximumWeight=0;
    residualRatio=zeros(p*n,1);
    for i=1:n
        Z=Y(:,:,i);residual=Z-(Z*V)*V';
        d=sqrt(sum(residual.^2,2));z=sqrt(sum(Z.^2,2));
        omega=max(0,lambda-d/gamma);weights=omega./(z.*d+1e-4);
        nonzeroRows=nonzeroRows+sum(weights>0);maximumWeight=max(maximumWeight,max(weights));
        covariance=covariance+Z'*(Z.*weights);
        residualRatio((i-1)*p+(1:p))=d/gamma;
    end
    covarianceFrobenius=norm(covariance,'fro');
    D=struct('RowNonzeroFraction',nonzeroRows/(p*n),'CovarianceFrobenius',covarianceFrobenius, ...
        'CovarianceRank',rank(covariance),'AllWeightsZero',nonzeroRows==0, ...
        'ZeroCovariance',covarianceFrobenius==0,'WeightMaximum',maximumWeight, ...
        'ResidualOverGammaMedian',median(residualRatio));
end
